def is_subseq_of(first: List[int], second: List[int]) -> bool:
    """
    Check if a list `first` is a subsequence of list `second`
    >>> is_subseq_of([1, 3, 5], [1, 2, 3, 4, 5])
    True
    >>> is_subseq_of([1, 4, 3], [1, 2, 3, 4, 5])
    False
    """
    if not first:
        return True
    it = iter(second)
    return all(elem in it for elem in first)


def print_sequences(seq: List[int]) -> None:
    """
    Prints all increasing sequences of a list `seq`
    >>> print_sequences([3, 1, 2, 4])
    3
    1
    1 2
    1 4
    2
    2 4
    4
    """
    for i in range(2 ** len(seq)):
        cur_seq = []
        for j in range(len(seq)):
            if (1 << j) & i != 0:
                cur_seq.append(seq[j])
        if all(x < y for x, y in zip(cur_seq, cur_seq[1:])):
            print(' '.join(map(str, cur_seq)))


def first_duplicate(seq: List[int]) -> int:
    """
    Returns first duplicate in a list `seq`
    >>> first_duplicate([1, 2, 3, 2, 1])
    2
    """
    seen = set()
    for num in seq:
        if num in seen:
            return num
        seen.add(num)
    return None


def merge_lists(first: List[int], second: List[int]) -> List[int]:
    """
    Merge two sorted lists into one sorted list
    >>> merge_lists([1, 3, 5], [2, 4, 6])
    [1, 2, 3, 4, 5, 6]
    """
    i = j = 0
    merged_list = []
    while i < len(first) and j < len(second):
        if first[i] < second[j]:
            merged_list.append(first[i])
            i += 1
        else:
            merged_list.append(second[j])
            j += 1
    while i < len(first):
        merged_list.append(first[i])
        i += 1
    while j < len(second):
        merged_list.append(second[j])
        j += 1
    return merged_list


