    False
    """
    return all(elem in second for elem in first)


def permutations(s: str) -> List[str]:
    """Returns all permutations of a string"""
    if len(s) == 1:
        return [s]
    res = []  # resulting list
    for i, v in enumerate(s):
        res += [v + p for p in permutations(s[:i] + s[i + 1:])]
    return res


def is_balanced(s: str) -> bool:
    """Checks if a parentheses string is balanced"""
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack.pop() not in '([{':
                return False
    return not stack


def check_parentheses(s: str) -> int:
    """Returns number of parentheses that have to be removed to make a string balanced"""
    stack = []
    count = 0
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack:
                stack.pop()
            else:
                count += 1
    return count + len(stack)


