def generate_bracket_sequences(n: int):
    """ Generate all correct bracket sequences of length 2*n
    >>> list(generate_bracket_sequences(1))
    ['<>']
    >>> list(generate_bracket_sequences(2))
    ['<><>', '<<>>']
    >>> list(generate_bracket_sequences(3))
    ['<><><>', '<><<<>>', '<<<>>><>', '<<<>>>']
    """
    def backtrack(seq, left, right):
        if len(seq) == 2 * n:
            yield seq
        else:
            if left < n:
                yield from backtrack(seq + '<', left + 1, right)
            if right < left:
                yield from backtrack(seq + '>', left, right + 1)

    return backtrack('', 0, 0)
