    # BEGIN SOLUTION
    N = len(grid)
    min_val = float('inf')
    for i in range(N):
        for j in range(N):
            min_val = min(min_val, grid[i][j])

    def get_neighbors(r, c):
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def dfs(r, c, path, k):
        if k == 0:
            return path
        min_path = None
        for nr, nc in sorted(get_neighbors(r, c), key=lambda x: grid[x[0]][x[1]]):
            new_path = path + [grid[nr][nc]]
            candidate_path = dfs(nr, nc, new_path, k-1)
            if min_path is None or candidate_path < min_path:
                min_path = candidate_path
        return min_path

    min_path = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] == min_val:
                path = dfs(r, c, [min_val], k-1)
                if min_path is None or path < min_path:
                    min_path = path

    return min_path
    # END SOLUTION
